mapper.select:
SELECT p.id, p.patient_no, p.name, p.gender, p.birth_date, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.phone, p.diagnose_date, p.allergy, p.comorbidity, p.risk_level, p.status, p.doctor_id, d.real_name AS doctor_name, p.last_visit_date, p.next_visit_date, p.remark, p.update_time FROM patient p LEFT JOIN sys_user d ON d.id = p.doctor_id AND d.deleted = 0 WHERE p.deleted = 0
AND p.name LIKE CONCAT('%', #{query.name}, '%')
AND p.patient_no LIKE CONCAT('%', #{query.patientNo}, '%')
AND p.phone LIKE CONCAT('%', #{query.phone}, '%')
AND p.risk_level = #{query.riskLevel}
AND p.status = #{query.status}
AND p.doctor_id = #{query.doctorId}
ORDER BY FIELD(p.risk_level, 'HIGH', 'MID', 'LOW'), p.next_visit_date ASC, p.id DESC
